//! Every answer in this file was produced by **MD4Lean**, not by the Rust code
//! it checks.
//!
//! `tests/data/md4lean-expected.json` is generated by
//! `tests/oracle/gen-md4lean-expected.ts`, which runs `MD4Lean.parse` under
//! `lake env lean` in the measurement target and prints the tree. The corpus is
//! every docstring in that package's IR plus hand-written cases for the corners
//! it does not contain. Regenerate with:
//!
//! ```text
//! deno run --allow-read --allow-write --allow-run --allow-env \
//!   crates/litedoc4-md/tests/oracle/gen-md4lean-expected.ts
//! ... --check      # verify the committed file
//! ... --full PATH  # write every case, for a check by hand (no test reads it)
//! ```
//!
//! The fixture is `include_str!`d, so these tests need no files at run time and
//! pass on a machine that has never seen the target package. It holds a
//! selected 533 of the 4,947 cases — a greedy cover of the constructors plus a
//! stride over the rest.
//!
//! **The other 4,414 are not checked**【判断 2026-08-16】. They used to be, by a
//! `the_whole_corpus` test reading a 5 MB `--full` recording out of
//! `/private/tmp` — which is emptied, so the test was either red or paid for by
//! re-running MD4Lean over every docstring in the package. What the oracle is
//! for is the **dialect** (which constructors MD4Lean's flags turn on, and how
//! it reads the corners), and that is a claim about the rules which the selected
//! cover states; [`the_corpus_still_covers_the_constructors`] is what keeps the
//! cover honest. The 4,414 are the price, stated rather than hidden.
//!
//! # What a passing run is worth
//!
//! The corpus is real docstrings, so it says the two parsers agree on what the
//! package actually contains. [`the_corpus_still_covers_the_constructors`] is
//! what stops it from decaying: it fails if a constructor stops appearing
//! anywhere, and it fails if `html`, `u` or `wikiLink` appears under the
//! docstring dialect, which cannot produce them — that would mean the flags
//! had drifted. Those three are covered by the handful of cases the generator
//! runs with other flags, so they are checked against MD4Lean too rather than
//! against something written here.

use std::collections::BTreeSet;

use litedoc4_md::{AttrText, Block, Document, Li, Text};
use serde::Deserialize;
use serde_json::{Value, json};

const FIXTURE: &str = include_str!("data/md4lean-expected.json");

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Expected {
    /// How the answers were produced, for the report a failure prints.
    oracle: String,
    lean_toolchain: String,
    md4lean_rev: Option<String>,
    /// How many distinct docstrings the target package's IR holds.
    ir_docstrings: usize,
    /// The docstring dialect, as MD4Lean's own constants add up.
    flags: u32,
    cases: Vec<Case>,
    /// The inputs that kill `MD4Lean.parse`, recorded rather than expected.
    crashes_md4lean: Vec<Crasher>,
}

#[derive(Deserialize)]
struct Case {
    /// Where the docstring came from: a declaration name, or `curated: ...`.
    what: String,
    /// What the oracle parsed this one with. Almost always the docstring
    /// dialect; a handful of `dialect: ...` cases vary it so that the three
    /// constructors that dialect cannot produce are still checked against
    /// MD4Lean rather than against a hand-written expectation.
    flags: u32,
    md: String,
    /// MD4Lean's tree, or `null` if `MD4Lean.parse` returned `none`.
    ast: Value,
}

#[derive(Deserialize)]
struct Crasher {
    what: String,
    flags: u32,
    md: String,
    /// How it died: `SIGSEGV`, `SIGABRT` or `exit 1`.
    how: String,
}

fn expected() -> Expected {
    serde_json::from_str(FIXTURE).expect("tests/data/md4lean-expected.json is valid")
}

// ------------------------------------------ the encoding `dump-ast.lean` uses

fn enc_attr(attr: &AttrText) -> Value {
    match attr {
        AttrText::Normal(s) => json!(["normal", s]),
        AttrText::Entity(s) => json!(["entity", s]),
        AttrText::NullChar => json!(["nullchar"]),
    }
}

fn enc_attrs(attrs: &[AttrText]) -> Value {
    Value::Array(attrs.iter().map(enc_attr).collect())
}

fn enc_text(text: &Text) -> Value {
    match text {
        Text::Normal(s) => json!(["normal", s]),
        Text::NullChar => json!(["nullchar"]),
        Text::Br(s) => json!(["br", s]),
        Text::SoftBr(s) => json!(["softbr", s]),
        Text::Entity(s) => json!(["entity", s]),
        Text::Em(ts) => json!(["em", enc_texts(ts)]),
        Text::Strong(ts) => json!(["strong", enc_texts(ts)]),
        Text::U(ts) => json!(["u", enc_texts(ts)]),
        Text::A {
            href,
            title,
            is_auto,
            children,
        } => json!([
            "a",
            enc_attrs(href),
            enc_attrs(title),
            is_auto,
            enc_texts(children)
        ]),
        Text::Img { src, title, alt } => {
            json!(["img", enc_attrs(src), enc_attrs(title), enc_texts(alt)])
        }
        Text::Code(parts) => json!(["code", parts]),
        Text::Del(ts) => json!(["del", enc_texts(ts)]),
        Text::LatexMath(parts) => json!(["latexMath", parts]),
        Text::LatexMathDisplay(parts) => json!(["latexMathDisplay", parts]),
        Text::WikiLink { target, children } => {
            json!(["wikiLink", enc_attrs(target), enc_texts(children)])
        }
    }
}

fn enc_texts(texts: &[Text]) -> Value {
    Value::Array(texts.iter().map(enc_text).collect())
}

fn enc_char(c: char) -> Value {
    json!(c.to_string())
}

fn enc_opt_char(c: Option<char>) -> Value {
    c.map_or(Value::Null, enc_char)
}

fn enc_li(li: &Li) -> Value {
    json!([
        li.is_task,
        enc_opt_char(li.task_char),
        li.task_mark_offset.map_or(Value::Null, |o| json!(o)),
        enc_blocks(&li.contents)
    ])
}

fn enc_block(block: &Block) -> Value {
    match block {
        Block::P(ts) => json!(["p", enc_texts(ts)]),
        Block::Ul { tight, mark, items } => json!([
            "ul",
            tight,
            enc_char(*mark),
            Value::Array(items.iter().map(enc_li).collect())
        ]),
        Block::Ol {
            tight,
            start,
            mark,
            items,
        } => json!([
            "ol",
            tight,
            start,
            enc_char(*mark),
            Value::Array(items.iter().map(enc_li).collect())
        ]),
        Block::Hr => json!(["hr"]),
        Block::Header { level, texts } => json!(["header", level, enc_texts(texts)]),
        Block::Code {
            info,
            lang,
            fence_char,
            content,
        } => json!([
            "code",
            enc_attrs(info),
            enc_attrs(lang),
            enc_opt_char(*fence_char),
            content
        ]),
        Block::Html(parts) => json!(["html", parts]),
        Block::BlockQuote(bs) => json!(["blockquote", enc_blocks(bs)]),
        Block::Table { head, body } => json!([
            "table",
            Value::Array(head.iter().map(|cell| enc_texts(cell)).collect()),
            Value::Array(
                body.iter()
                    .map(|row| Value::Array(row.iter().map(|cell| enc_texts(cell)).collect()))
                    .collect()
            )
        ]),
    }
}

fn enc_blocks(blocks: &[Block]) -> Value {
    Value::Array(blocks.iter().map(enc_block).collect())
}

fn enc_document(doc: &Document) -> Value {
    enc_blocks(&doc.blocks)
}

// ---------------------------------------------------------------- the checks

/// Renders an input so a failure names the code points rather than printing
/// control characters into the terminal.
fn show(s: &str) -> String {
    let head: String = s
        .chars()
        .take(200)
        .map(|c| {
            if c.is_ascii_graphic() || c == ' ' {
                c.to_string()
            } else {
                format!("<U+{:04X}>", c as u32)
            }
        })
        .collect();
    if s.chars().count() > 200 {
        format!("{head}...")
    } else {
        head
    }
}

/// Compares one case, returning a description of the disagreement.
///
/// The docstring cases go through [`litedoc4_md::parse`] rather than through
/// `parse_with_flags(.., case.flags)`, so that the default this crate hands
/// every caller is the thing being checked. `docstring_flags` is the *oracle's*
/// number, not this crate's constant: comparing against the constant would
/// make the test follow it wherever it drifted.
fn check(case: &Case, docstring_flags: u32) -> Option<String> {
    let got = if case.flags == docstring_flags {
        litedoc4_md::parse(&case.md)
    } else {
        litedoc4_md::parse_with_flags(&case.md, case.flags)
    };
    match (&case.ast, got) {
        (Value::Null, Err(_)) => None,
        (Value::Null, Ok(_)) => Some(format!(
            "{}: MD4Lean refused this input and we parsed it",
            case.what
        )),
        (_, Err(error)) => Some(format!(
            "{}: {error}\n  input: {}",
            case.what,
            show(&case.md)
        )),
        (want, Ok(doc)) => {
            let mine = enc_document(&doc);
            if &mine == want {
                None
            } else {
                Some(format!(
                    "{}\n  input: {}\n  MD4Lean: {want}\n  here:    {mine}",
                    case.what,
                    show(&case.md)
                ))
            }
        }
    }
}

#[test]
fn the_fixture_is_md4leans_own_output() {
    let e = expected();
    assert!(e.oracle.contains("MD4Lean.parse"), "{}", e.oracle);
    assert_eq!(e.lean_toolchain, "leanprover/lean4:v4.31.0");
    assert_eq!(
        e.md4lean_rev.as_deref(),
        Some("6a3fb240133bcb7e1a066fdc784b3fdc304e3fc5"),
        "the pin in vendor/md4c/PROVENANCE.md"
    );
    // MD4Lean's own constants have to add up to this crate's default, or the
    // oracle is answering a different question. Both sides wrote the bitmask
    // down independently: `MD4Lean.lean` and `src/flags.rs`.
    assert_eq!(e.flags, litedoc4_md::DOCSTRING_FLAGS);
    // 実測: the target package's IR holds this many distinct docstrings.
    assert_eq!(e.ir_docstrings, 4_858);
    // A fixture that shrank is a fixture that stopped covering something.
    assert!(e.cases.len() >= 500, "only {} cases", e.cases.len());
    assert_eq!(e.crashes_md4lean.len(), 3);

    // Nearly every case is the real dialect; the handful that are not are
    // there on purpose and are named as such.
    let (default, varied): (Vec<_>, Vec<_>) = e.cases.iter().partition(|c| c.flags == e.flags);
    assert!(
        default.len() > 500,
        "only {} default-dialect cases",
        default.len()
    );
    assert!(
        varied.len() >= 5,
        "the dialect-varying cases are gone, so `u`, `wikiLink` and `html` are unchecked"
    );
    for case in varied {
        assert!(case.what.starts_with("dialect: "), "{}", case.what);
    }
}

#[test]
fn every_case_matches_md4lean() {
    let e = expected();
    let cases = e.cases;
    let failures: Vec<String> = cases.iter().filter_map(|c| check(c, e.flags)).collect();
    assert!(
        failures.is_empty(),
        "{} of {} cases disagree with MD4Lean:\n{}",
        failures.len(),
        cases.len(),
        failures
            .iter()
            .take(20)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}

/// Which constructors the committed fixture actually exercises.
fn tags_in(value: &Value, into: &mut BTreeSet<String>) {
    let Some(items) = value.as_array() else {
        return;
    };
    if let Some(Value::String(tag)) = items.first() {
        into.insert(format!("{tag}/{}", items.len() - 1));
    }
    for item in items {
        tags_in(item, into);
    }
}

#[test]
fn the_corpus_still_covers_the_constructors() {
    let e = expected();
    let mut tags = BTreeSet::new();
    let mut docstring_tags = BTreeSet::new();
    for case in &e.cases {
        tags_in(&case.ast, &mut tags);
        if case.flags == e.flags {
            tags_in(&case.ast, &mut docstring_tags);
        }
    }

    // Every branch of the builder the docstring dialect can reach.
    for wanted in [
        "p/1",
        "ul/3",
        "ol/4",
        "hr/0",
        "header/2",
        "code/4", // a code block
        "blockquote/1",
        "table/2",
        "normal/1",
        "nullchar/0",
        "br/1",
        "softbr/1",
        "entity/1",
        "em/1",
        "strong/1",
        "a/4",
        "img/3",
        "code/1", // a code span
        "del/1",
        "latexMath/1",
        "latexMathDisplay/1",
    ] {
        assert!(docstring_tags.contains(wanted), "no case produces {wanted}");
    }

    // And the three it cannot. `MD_FLAG_NOHTML` is why raw HTML never becomes
    // a block; `MD_FLAG_UNDERLINE` and `MD_FLAG_WIKILINKS` are off. Any of
    // them turning up under the docstring dialect means the flags drifted —
    // and each still has to turn up *somewhere*, or the code that builds it is
    // unchecked. That is what the `dialect: ...` cases are for.
    for only_elsewhere in ["html/1", "u/1", "wikiLink/2"] {
        assert!(
            !docstring_tags.contains(only_elsewhere),
            "{only_elsewhere} appeared; the docstring dialect is not the one doc-gen4 uses"
        );
        assert!(
            tags.contains(only_elsewhere),
            "nothing in the corpus produces {only_elsewhere}, so that branch is unchecked"
        );
    }
}

/// The inputs that kill `MD4Lean.parse`, and what this crate does instead.
///
/// All three are undefined behaviour on the Lean side, so there is no tree to
/// match; what is pinned here is that none of them crashes us, and what we
/// chose: U+FFFD for a NUL in verbatim content (CommonMark's rule, and what
/// doc-gen4 renders `.nullchar` as), and an empty body for a table with no
/// body rows.
#[test]
fn the_inputs_that_kill_md4lean_parse_here() {
    let crashers = expected().crashes_md4lean;
    assert!(
        crashers.iter().any(|c| c.how == "SIGSEGV"),
        "the NUL-in-a-code-block crash is no longer recorded"
    );
    for crasher in &crashers {
        match litedoc4_md::parse_with_flags(&crasher.md, crasher.flags) {
            Ok(doc) => assert!(!doc.blocks.is_empty(), "{}", crasher.what),
            // The one shape MD4Lean's ADT cannot hold at all. Refusing is the
            // decision; it is only reachable with flags doc-gen4 never sets.
            Err(litedoc4_md::Error::Unrepresentable(_)) => {
                assert!(crasher.what.contains("raw html"), "{}", crasher.what);
            }
            Err(e) => panic!("{}: {e}", crasher.what),
        }
    }

    let doc = litedoc4_md::parse("```\na\0b\n```\n").expect("a NUL in a code block");
    let Block::Code { content, .. } = &doc.blocks[0] else {
        panic!("{:?}", doc.blocks)
    };
    // The NUL survives *twice*: md4c reports it as `MD_TEXT_NULLCHAR` and then
    // resumes the verbatim text at the NUL rather than after it
    // (`md4c.c:387-408` advances `off` but not `str`). So the replacement
    // character this crate substitutes is followed by the byte itself. That is
    // md4c's behaviour, not a choice made here.
    assert_eq!(content.concat(), "a\u{FFFD}\0b\n");

    let doc = litedoc4_md::parse("| a | b |\n|---|---|\n").expect("a table with no body");
    assert_eq!(
        doc.blocks,
        vec![Block::Table {
            head: vec![
                vec![Text::Normal("a".to_owned())],
                vec![Text::Normal("b".to_owned())]
            ],
            body: vec![],
        }]
    );
}

/// A NUL in ordinary text is *not* one of those cases: md4c reports it as
/// `MD_TEXT_NULLCHAR` in a position where MD4Lean's types have a constructor
/// for it, so it is checked against the oracle like everything else. This
/// states which side of the line it is on.
#[test]
fn a_nul_in_ordinary_text_is_a_normal_case() {
    let doc = litedoc4_md::parse("a\0b\n").expect("a NUL in text");
    assert_eq!(
        doc.blocks,
        vec![Block::P(vec![
            Text::Normal("a".to_owned()),
            Text::NullChar,
            Text::Normal("b".to_owned()),
        ])]
    );
    // And inside a code span md4c does not split at all: the NUL stays in the
    // string, which is why that case does not crash MD4Lean either.
    let doc = litedoc4_md::parse("`a\0b`\n").expect("a NUL in a code span");
    assert_eq!(
        doc.blocks,
        vec![Block::P(vec![Text::Code(vec!["a\0b".to_owned()])])]
    );
}
